import { CmdDrawerState } from "./ctx";
import { NATIONAL_CONVERSION_AVG } from "../../../data/command";

const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
const stat = (v: React.ReactNode, l: string) => (
 <div className="ci-stat"><span className="ci-stat__v">{v}</span><span className="ci-stat__l">{l}</span></div>
);

export function CmdDrawer({ state, onClose, onAction }:
 { state: CmdDrawerState | null; onClose: () => void; onAction: (a: string) => void }) {
 if (!state) return null;
 const { kind, data } = state;

 let title = "", sub = "", body: React.ReactNode = null, actions: string[] = [];

 if (kind === "kpi") {
 title = data.label; sub = data.drill;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(data.value.toLocaleString(), "Current")}
 {stat(<span style={{ color: data.delta >= 0 ? "var(--ci-green)" : "var(--ci-red)" }}>{data.delta >= 0 ? "+" : ""}{data.delta}%</span>, "Trend")}
 {stat(<Chip status={data.status}>{data.status}</Chip>, "Status")}
 </div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.support}. This opens the underlying filtered cohort in the analytics workspace.</p>
 </>;
 actions = ["Investigate", "Compare", "Add to Watchlist"];
 } else if (kind === "region") {
 title = data.name + " Region"; sub = `${data.discovered.toLocaleString()} discovered · ${data.conversion}% conversion`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(data.assessed.toLocaleString(), "Assessed")}
 {stat(data.highPotential, "High potential")}
 {stat(data.pathways.toLocaleString(), "Dev pathways")}
 {stat(data.fastest, "Fastest sport")}
 </div>
 <div className="ci-insight" style={{ marginBottom: 12 }}>
 <span className="ci-insight__icon">◆</span>
 <div className="ci-insight__txt" style={{ fontSize: 12 }}>{data.insight}
 {data.conversion < NATIONAL_CONVERSION_AVG && <> <b>({(NATIONAL_CONVERSION_AVG - data.conversion).toFixed(1)}pts below national average)</b></>}</div>
 </div>
 </>;
 actions = ["Investigate", "Create Intervention", "Request Assessment", "Add to Watchlist"];
 } else if (kind === "cycle") {
 title = `${data.year} Cycle Readiness`; sub = `${data.headline} · overall ${data.overall}%`;
 body = <>
 <div style={{ marginBottom: 14 }}>{data.dims.map((d: any) => <Bullet key={d.label} label={d.label} value={d.value} />)}</div>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Top contributing sports</div>
 <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 14 }}>{data.sports.map((s: string) => <Chip key={s} status="cyan">{s}</Chip>)}</div>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Cohort</div>
 <p className="ci-dim" style={{ fontSize: 12.5, margin: "0 0 14px" }}>{data.cohorts}</p>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Readiness gaps</div>
 <ul style={{ margin: "0 0 14px", paddingLeft: 16 }}>{data.gaps.map((g: string) => <li key={g} className="ci-dim" style={{ fontSize: 12.5, marginBottom: 4 }}>{g}</li>)}</ul>
 <div className="ci-insight"><span className="ci-insight__icon">◆</span><div className="ci-insight__txt" style={{ fontSize: 12 }}><b>Recommended:</b> {data.rec}</div></div>
 </>;
 actions = ["Recommend Development Plan", "Create Intervention"];
 } else if (kind === "risk") {
 title = data.subject; sub = `${data.sev} · open ${data.age}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(<Chip status={data.sev === "CRITICAL" ? "red" : data.sev === "HIGH" ? "amber" : "cyan"}>{data.sev}</Chip>, "Severity")}
 {stat(data.count, "Affected")}
 {stat(data.owner, "Owner")}
 {stat(data.age, "Time open")}
 </div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.issue}. Recommended next step: <b style={{ color: "var(--ci-text)" }}>{data.next}</b>.</p>
 </>;
 actions = ["Investigate", "Create Intervention", "Assign Specialist", "Schedule Assessment"];
 } else if (kind === "velo") {
 if (data) {
 title = data.name; sub = `${data.sport} · age ${data.age} · ${data.stage}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 12, marginBottom: 14 }}>
 {stat("P" + data.perf, "Benchmark")}
 {stat(<span style={{ color: "var(--ci-green)" }}>+{data.growth}%</span>, "Improvement")}
 {stat(data.conf, "Confidence")}
 </div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.perf < 50 && data.growth > 50 ? "Emerging athlete accelerating faster than cohort — strong candidate for accelerated assessment." : "Tracking within expected development band."}</p>
 </>;
 actions = ["Open Athlete", "Compare", "Add to Watchlist", "Request Assessment"];
 } else {
